import{_ as s,O as a,o as r,c as i,a as o,i as n,f as l}from"./chunks/framework.fmIt2z2h.js";const g=JSON.parse('{"title":"D.30　生态、资源、公地与可持续生活","description":"","frontmatter":{"title":"D.30　生态、资源、公地与可持续生活","xkChars":802,"xkLessons":{"D.30":{"title":"D.30　生态、资源、公地与可持续生活","lead":"物质约束、取得条件、权利和恢复终点分别核验；组合过阈值不自动证明显著统计交互或全部系统恢复。","explanation":["原文定位：第4999—5016行，原站定位/theory/appendix-d/d-30#section-d-30。本题切片及完整用户原稿均在source目录，可逐字回查。","短引文：“守恒账不提供唯一价值分配”。自然过程、制度知识市场生活经具体接口相连；社会选择能改资源使用风险分配，不能以定义取消水文物质约束。资源系统、单位、取用者、在用规则和结果保留专业区分。[T-main]","林覆、物种、燃料可及与家庭生活不能互换；食物库存、组织可征调物资与家庭实际取得也不同。Sen1981第433–435页把总体粮食可得量与个人能够取得足够食物的商品组合分开：总体短缺可以影响个人饥饿，但总体数量本身不能说明每个人能取得什么。取得集合还与初始禀赋、交换或生产机会，以及社会保障等制度性给付相联系。第434页脚注5特别说明，此处entitlement使用为描述性分析，并不直接裁定何种分配正当。供给、获取、救济到达、营养疾病后果因此须分别提出证据需求。[T-main；P-SEN1981]","共池资源的排除成本与减损性质不是法律共有身份。进入取用管理排除转让权分别查；集体组织和工程支持可以互补，地方规则也不天然公平。讨论谁能参与和谁承担成本，不能因名叫公地就补出具体权利。[T-main]","能源转型要分连续燃料流、建设和在用存量、矿物用途、精炼品质以及可比服务。物质守恒能约束可能性，却不自动分配价值责任；GDP、物质、生活、照护、生态结果可以不同向，不强行合成一个健康总分。[T-main]","取水、净耗、蒸散、回流、回补、水位不同。田间效率升后扩面积可使局部节水与总净耗增加并存；信息改善若未进入取用约束维护，不能保证总体结果。邻近污染源也不独自识别个人健康效应，须相应暴露及因果材料。[T-main]","环境正义的分配承认程序补救各有证据。气候中的历史贡献、当前能力、未来风险、适应需要也不同，测量、机制、情景、规范不确定性分别写，不把一个维度直接换成赔偿份额。[T-main]","国际法院2025年7月23日咨询意见§§414—415解释巴黎协定第8条是合作促进型支持、不是责任赔偿基础，但不构成排除一般国家责任的明确特别法。§§433—435区分责任成立与特定损害的修复赔偿因果，多因不当然免责，也不可推定因果。[P-ICJ]","这几个段落没有给某国应付某人的金额，科学结果也不直接授处置权。reparation保留修复赔偿的广义，不只金钱。合作支持、法律责任和具体损害请求需各自法源对象条件，不能从一机制限制推出所有其他依据均无效。[T-main][P-ICJ]","实际生态研究参照：Marshall等2013论文在四地点操弄围栏与模拟海狸坝，测柳树高度、生物量。十年后组合高度均值248cm超过2m阈值，单围栏160、单坝174、对照117cm；实际操弄不是随机重引入狼。[P-MARSHALL]","论文图2/结果中高度与生物量交互效应预测区间均跨0，因此不能仅以组合过阈值称显著统计协同。讨论还承认坝可能改变水和养分，不将效果只归水位。局部柳树高度目标也不等物种、食物、用水和人的生活全面恢复。[P-MARSHALL]","保育可能同时涉及非人个体、种群和生态过程。科学知识、地方知识、法律代理有不同资格，一位置保护成效不自动抵销另一位置损失。正文连接§2.8、第五部分、§6.9、第十二及十四部分，核条件、反馈、目标、责任和分项后果。[T-main]","八入口为30.01社会生态具体接口；30.02公地共同资源的权利治理；30.03能源与物质代谢的流存量；30.04农业食物水的取得与净耗；30.05环境正义风险分配；30.06气候适应跨代责任；30.07增长退增长多种福祉尺度；30.08保育地方社会非人价值。导航不替代所有专业文献与现场测量。[T-main]"],"argumentSteps":["明确资源对象、实际操弄和结果单位。","区分物质库存流量、家庭获取与营养生活。","分进入取用管理排除转让权限。","先列分项结果与阈值，再检验交互和机制。","分合作支持责任赔偿，保存不同位置的收益损失。"],"distinctions":[{"leftTitle":"取水量","leftText":"从来源提取。","rightTitle":"净消耗","rightText":"需扣回流等并定边界，不能直接等同。"},{"leftTitle":"共池性质","leftText":"排除成本与减损。","rightTitle":"共有法律身份","rightText":"具体权属不同问题。"},{"leftTitle":"组合过阈值","leftText":"指定结果达到门槛。","rightTitle":"显著交互","rightText":"特定统计尺度上的另项判断。"},{"leftTitle":"合作支持","leftText":"机制安排的支持。","rightTitle":"损害赔偿","rightText":"另核责任与特定因果。"}],"boundaries":["原文教学反例：效率提高后扩面积，总净耗可能增加。","原文边界：围栏和水文设施操弄不能改名随机重引入捕食者。","教学反例：加法作用恰好一起过阈值，不含交互项。"],"questions":["组合达标证明显著协同吗？","库存足证明每户取得吗？","多原因必然免责吗？","一项生态改善抵销其他损失吗？"],"diagramPath":"/reading-assets/S-D-30/figures/d30-interface.png","caseLinks":[{"title":"2013年围栏与模拟海狸坝的柳树恢复研究","href":"https://sites.warnercnr.colostate.edu/davidcooper/wp-content/uploads/sites/15/2017/02/MarshallHobbsCooper2013RSPB.pdf"},{"title":"Sen1981：总体粮食可得量与个人取得条件","href":"https://doi.org/10.2307/1882681"}],"caseNotes":[{"title":"2013年围栏与模拟海狸坝的柳树恢复研究","text":"四地点析因操弄，十年组合高度均值248cm过2m；单围栏160、单坝174、对照117cm，交互预测区间跨0。","sourceLabel":"Marshall, Hobbs & Cooper 2013: Stream hydrology limits recovery of riparian ecosystems after wolf reintroduction","sourceUrl":"https://sites.warnercnr.colostate.edu/davidcooper/wp-content/uploads/sites/15/2017/02/MarshallHobbsCooper2013RSPB.pdf","sourceLocator":"印刷2—6页（本存档PDF3—7），§2方法、§3结果/图2、§4讨论","boundary":"不是随机重引入狼、不是显著统计协同或完整生态系统恢复；未复算原数据。","href":"https://sites.warnercnr.colostate.edu/davidcooper/wp-content/uploads/sites/15/2017/02/MarshallHobbsCooper2013RSPB.pdf"}],"sourceRefs":[{"section":"D.30","start_line":4999,"end_line":5016,"startLine":4999,"endLine":5016}],"outputId":"section-d-30","sourceHash":"df579dbdbb68442b1781b066606c267761f0a1673fbd034ce93eeeb41641439f","teachingExamples":[{"title":"教学构造：单亩省水、总量增加","text":"人工原100亩每亩净耗10，总1000；改后每亩8但扩至150亩，总1200。每亩下降20%，总净耗增加20%，两者同时成立。","assumptions":"均为净消耗同口径，未把取水当净耗；面积人工给定。","boundary":"不解释真实扩种因果或水位变化。"},{"title":"教学构造：过阈值不等有交互","text":"人工结果y=1+0.6A+0.6B，A/B各为0或1。对照1、单项1.6、组合2.2，阈值2只有组合达标；交互差2.2−1.6−1.6+1=0。无需交互也能出现组合独过阈值。","assumptions":"确定加法构造，无抽样误差；不是柳树原数据。","boundary":"实证显著性还要误差模型，不能用人工零替代论文检验。"}],"counterexamples":[{"identity":"constructed_boundary","text":"原文教学反例：效率提高后扩面积，总净耗可能增加。","effect":"限制本节的无条件延伸；不否定具有独立依据的有限判断。","sourceIds":["T-main"]},{"identity":"source_counterexample","text":"原文边界：围栏和水文设施操弄不能改名随机重引入捕食者。","effect":"限制本节的无条件延伸；不否定具有独立依据的有限判断。","sourceIds":["T-main"]},{"identity":"constructed_boundary","text":"教学反例：加法作用恰好一起过阈值，不含交互项。","effect":"限制本节的无条件延伸；不否定具有独立依据的有限判断。","sourceIds":["T-main"]}],"questionAnswers":[{"question":"组合达标证明显著协同吗？","answer":"不能，阈值与统计交互不同。","basis":"核心反例。"},{"question":"库存足证明每户取得吗？","answer":"不，获取与救济到达需证据。","basis":"接口。"},{"question":"多原因必然免责吗？","answer":"不能，也不能反向直接推定特定损害因果。","basis":"ICJ限定。"},{"question":"一项生态改善抵销其他损失吗？","answer":"不自动抵销，位置与指标分开。","basis":"价值边界。"}],"figures":[{"path":"/reading-assets/S-D-30/figures/d30-interface.png","alt":"供给库存、组织动员、家庭取得、营养生活分开。","caption":"据D.30。"},{"path":"/reading-assets/S-D-30/figures/d30-ecology.png","alt":"围栏×坝实际处理，组合248过200，不等显著交互。","caption":"2013研究指定范围。"},{"path":"/reading-assets/S-D-30/figures/d30-math.png","alt":"单位净耗下降总耗增加；加法组合也可单独越阈值。","caption":"教学构造。"}],"diagramBrief":"三图展示物质取得、实际生态操弄与两人工算例。","applicability":{"realCase":"applicable","diagram":"applicable","reason":"本单元涉及方法判断，真实来源仅支持所列事实；图与教学构造分别保留其身份。"},"openQuestions":["未读补充材料，未独立重算生态原数据。","Sen1981后文历史饥荒个案、完整形式展开与相关数据仍未核读；本节只借指定概念页说明总体与个人取得条件的区别。"],"taskId":"S-D-30","sources":[{"id":"T-main","title":"Xikari著《Xikari-条件结构与转化论》","url":"/reading-assets/theory.md","source_type":"theory_source","version_or_date":"manuscript-20261013-df579dbdbb68；文本自述2026年10月","locator":"§D.30，第4999—5016行","claim_support":["资源生态多尺度、权利、正义气候责任、恢复及八入口。"],"limits":["支持当前稿的文本含义与明确限定的推理；不自行证明经验普遍性、实施效果或读者学习成效。"],"access_status":"read"},{"id":"P-MARSHALL","title":"Marshall, Hobbs & Cooper 2013: Stream hydrology limits recovery of riparian ecosystems after wolf reintroduction","url":"https://sites.warnercnr.colostate.edu/davidcooper/wp-content/uploads/sites/15/2017/02/MarshallHobbsCooper2013RSPB.pdf","source_type":"primary","version_or_date":"2013，Proc R Soc B280:20122977","locator":"印刷2—6页（本存档PDF3—7），§2方法、§3结果/图2、§4讨论","claim_support":["四地点围栏×模拟海狸坝操弄；十年后组合均值248cm超过2m，单围栏160、单坝174、对照117；交互预测区间跨0；坝可同时改变水与养分。"],"limits":["本人读指定方法结果讨论及图注，未读补充材料或复算原始数据；不认领随机放狼处理、显著协同或完整生态全面恢复。"],"access_status":"partially_read"},{"id":"P-ICJ","title":"ICJ2025气候变化咨询意见，联合国A/79/979","url":"https://documents.un.org/api/symbol/access?l=en&s=A%2F79%2F979&t=pdf","source_type":"primary","version_or_date":"2025-07-23意见；2025-08-04联合国转送版本","locator":"2025-07-23意见，§§414—415（127—128页）、433—435（132—133页）","claim_support":["巴黎协定第8条为合作支持而非赔偿基础，但不排除一般国家责任；责任与特定损害修复赔偿因果证明分开，多因不当然免责也不能推定因果。"],"limits":["本人直接读指定段与必要上下文；未通读142页，不据此认定某国对具体主体的赔偿份额；reparation不限金钱。"],"access_status":"partially_read"},{"id":"P-SEN1981","title":"Amartya Sen: Ingredients of Famine Analysis: Availability and Entitlements","url":"https://doi.org/10.2307/1882681","source_type":"primary","version_or_date":"Quarterly Journal of Economics 96(3), August 1981, pp.433–464","locator":"印刷433–435页，含434页脚注5；本地JSTOR扫描件PDF2–4，另核PDF1题录封面","claim_support":["区分粮食总体可得量与个人能够取得足够食物的商品组合；总体短缺可以影响个体饥饿，但不能以总体数量代替个人取得条件。","第435页把取得集合与初始禀赋、交换或生产机会及制度性给付相连接；第434页脚注5明确本文entitlement使用为描述性而非规范性。"],"limits":["只读指定433–435页与题录封面；第435页末句续下页，未据未读续文展开。","未读后文三个饥荒个案、完整形式展开或复核历史数据；不据此判定任何实际饥荒的原因或个体法律权利。"],"access_status":"partially_read"}],"lecturePath":"/reading-assets/S-D-30/lecture.md","sourcesPath":"/reading-assets/S-D-30/sources.json","sourceSlicePath":"/reading-assets/S-D-30/source/S-D-30.md","supplementaryFiles":[],"diagramsPath":"/reading-assets/S-D-30/diagrams.md","keyTerms":[{"term":"entitlement（Sen 1981的本文用法）","text":"在给定社会情境下，一个人通过当时社会提供的合法途径能够取得的商品组合；生产、交换和制度性给付都可能进入。第434页脚注5说明这是描述性而非规范性用法，不宣告既有分配已经正当。","href":"https://doi.org/10.2307/1882681","ref":"印刷433–435页"},{"term":"粮食总体可得量与个人取得条件","text":"前者问总体有多少食物，后者问某个人实际能够取得哪些足以维持生活的组合；总体短缺可以影响后者，两项判断仍需分别进行。","href":"https://doi.org/10.2307/1882681","ref":"印刷434–435页"}]}}},"headers":[],"relativePath":"theory/appendix-d/d-30.md","filePath":"theory/appendix-d/d-30.md"}'),c={name:"theory/appendix-d/d-30.md"};function d(p,e,u,m,f,h){const t=a("SectionLesson");return r(),i("div",null,[e[0]||(e[0]=o("",1)),n(t,{section:"D.30"}),e[1]||(e[1]=l("div",{class:"theory-source"},null,-1))])}const y=s(c,[["render",d]]);export{g as __pageData,y as default};
